<?php
namespace App\Models;
use App\Models\Concerns\HasSpanishDatabase;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Factories\HasFactory;
class Ticket extends Model { use HasFactory,HasSpanishDatabase; protected $table='solicitudes'; protected $fillable=['code','school_id','equipment_id','equipment_brand','requester_id','assigned_to','category','priority','status','subject','description','resolved_at']; protected array $attributeMap=['code'=>'codigo','school_id'=>'unidad_educativa_id','equipment_id'=>'equipo_id','equipment_brand'=>'marca_equipo','requester_id'=>'solicitante_id','assigned_to'=>'tecnico_asignado_id','category'=>'categoria','priority'=>'prioridad','status'=>'estado','subject'=>'asunto','description'=>'descripcion','resolved_at'=>'resuelto_en']; protected array $valueMap=['category'=>['hardware'=>'hardware','software'=>'software','connectivity'=>'conectividad'],'priority'=>['low'=>'baja','medium'=>'media','high'=>'alta','critical'=>'critica'],'status'=>['pending'=>'pendiente','diagnosis'=>'diagnostico','waiting_parts'=>'espera_repuestos','in_progress'=>'en_progreso','resolved'=>'solucionado','closed'=>'cerrado','cancelled'=>'cancelado']]; protected $casts=['resuelto_en'=>'datetime']; public function school(){return $this->belongsTo(School::class,'unidad_educativa_id');} public function equipment(){return $this->belongsTo(Equipment::class,'equipo_id');} public function requester(){return $this->belongsTo(User::class,'solicitante_id');} public function technician(){return $this->belongsTo(User::class,'tecnico_asignado_id');} public function histories(){return $this->hasMany(TicketStatusHistory::class,'solicitud_id')->latest();} public function interventions(){return $this->hasMany(Intervention::class,'solicitud_id')->latest('realizado_en');} }
